// === Tab: mySketch ===
let w = 900, h = 900;
let s = 10;
let type;
let pal = ['#ECAA9C','#B1D1C6', '#2E5B8B', '#F2CA60', '#d4c7a3', '#DE7830', '#513C2C', '#1F3858', '#C9292E', '#bfb8a3'];
var m = 4;
let tSize = 8;

function generateStationName() {
	let chars = 'abcdefghijklmnopqrstuvwxyz';
	let name = '';
	let size = int(random(5, 8));
	for ( var i = 0; i < size; i++ ) {
		name += chars.charAt(Math.floor(Math.random() * chars.length));
	}
	return name.charAt(0).toUpperCase() + name.slice(1).toLowerCase();
}

function mousePressed() {
	redraw();
}

let myFont;
function preload() {
	myFont = loadFont("https://openprocessing.org/sketch/1766876/files/Ubuntu-Regular.ttf");
}

function setup() {
  createCanvas(w, h);
	pixelDensity(2);
  noLoop();
  smooth();
  rectMode(CENTER);
  colorMode(HSB, 360, 100, 100, 100);

	textFont(myFont);
	textSize(tSize);
  textAlign(CENTER, CENTER);
}

function drawLine(col) {
  var origin_x = int( random(w/m, w*(m-1)/m) / s) * s;
  var origin_y = int( random(h/m, h*(m-1)/m) / s) * s;

  var cc = color(col);
  cc.setAlpha(80);
  var num = int(random(8, 16));

  var dir;
  var startDir = random();
  if(startDir < 0.25) {
    dir = 1;
  } else if(startDir < 0.5) {
    dir = 2;
  } else if(startDir < 0.75) {
    dir = 3;
  } else {
    dir = 4;
  }
  // dir type
  // 1 ... ↓
  // 2 ... ↑
  // 3 ... →
  // 4 ... ←

  push();
  translate(origin_x, origin_y);
  var step;
  var px1 = 0, py1 = 0;
  var px2 = 0, py2 = 0;
  var t = s-s/10, u = t*0.5;

  for(let i = 0; i < num; i++) {
    step = int( random(6, 12));

		if(random() < 0.1) {
			textSize(tSize*1.5);
			textStyle(BOLD);
		} else {
			textStyle(NORMAL);
			textSize(tSize);		
		}

		noStroke();
		fill(5);

    if(dir == 1) {
      dir = getDir(1, 3, 4);
      px1 = 0;
      py1 = s;
      px2 = 0;
      py2 = step*s;
			textAlign(LEFT, CENTER);
			text(generateStationName(), px1 + t, py1);
    } else if(dir == 2) {
      dir = getDir(2, 3, 4);
      px1 = 0;
      py1 = -s;
      px2 = 0;
      py2 = -step*s;
			textAlign(LEFT, CENTER);
			text(generateStationName(), px1 + t, py1);
    } else if(dir == 3) {
      dir = getDir(1, 2, 3);
      px1 = s;
      py1 = 0;
      px2 = step*s;
      py2 = 0;
			textAlign(CENTER, BOTTOM);
			text(generateStationName(), px1, py1 + t*1.5);
    } else if(dir == 4) {
      dir = getDir(1, 2, 4);
      px1 = -s;
      py1 = 0;
      px2 = -step*s;
      py2 = 0;
			textAlign(CENTER, BOTTOM);
			text(generateStationName(), px1, py1 - t);
    }
		strokeWeight(t);
    stroke(cc);
    noFill();
    line(px1, py1, px2, py2);

    noStroke();
    fill(0, 0, 97, 100);
		if(random() < 0.1) {
		  circle(px2, py2, u*1.5);
		} else {
	    circle(px2, py2, u);
		}

    translate(px2, py2);
  }
  pop();
}

function getStationName()
{
	return Math.random().toString(32).substring(2, 10); 
}

function draw() {
  background(220);

  var nx, ny, m, n, col, v;

  rectMode(CENTER);
  strokeWeight(5);
  stroke(220);

  for(let i = 0; i < 12; i++) {
    col = color( getColor() );
    col.setAlpha(50);
    fill(col);
    var px = int( random(s*15, w-s*15)/s ) * s;
    var py = int( random(s*15, h-s*15)/s ) * s;
    var a = int( random(5, 15) );
    var b = int( random(5, 15) );
    rect(px, py, s*2*a, s*2*b, 10);
  }

  drawGrids();

  for(let i = 0; i < 24; i++) {
    col = getColor();
    drawLine(col);    
  }


  drawFrame();
}


function drawGrids() {
  stroke(0,0,10,100);
  strokeWeight(1.5);
  noFill();
  var tx = int(w / s);
  var ty = int(h / s);
  for(let i = 0; i < ty; i++) {
    cy = i * s;
    for(let j = 0; j < tx; j++) {
      cx = j * s;
      point(cx, cy);
    }
  }
}

function drawFrame() {
  noStroke();
  fill(220);

	var s = 10;

  rect(s*2-1, h/2, s*4, h);
  rect(w-s*2+1, h/2, s*4, h);

  rect(w/2, s*2-1, w, s*4);
  rect(w/2, h-s*2+1, w, s*4);
}

function getDir(n1, n2, n3) {
  var dd = random();

  if(dd < 0.333) {
    return n1;
  } else if(dd < 0.666) {
    return n2;
  } else {
    return n3;
  }
}


function getColor() {
  var l = pal.length;
  var cc = random();
  shuffle(pal, true);

  if(cc < 1/l) {
    return pal[0];
  } else if (cc < 2/l) {
    return pal[1];
  } else if (cc < 3/l) {
    return pal[2];
  } else if (cc < 4/l ) {
    return pal[3];
  } else if (cc < 5/l) {
    return pal[4];
  } else if (cc < 6/l) {
    return pal[5];
  } else if (cc < 7/l) {
    return pal[6];
  } else if (cc < 8/l) {
    return pal[7];
  } else if (cc < 9/l) {
    return pal[8];
  } else {
    return pal[9];
  }
}

